// Builds the self-hosted icon files from Iconify (https://iconify.design).
// Run after adding an icon name to the source:   npm run icons
// Needs network access once; the generated files are committed, so the apps never contact Iconify at runtime.
//   engine/js/icons.js   Lucide icons for the generated study sites
//   public/js/icons.js   Solar (linear) icons for the dashboard
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { CHAPTER_ICONS } from '../server/lib/iconNames.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const TARGETS = [
  { name: 'engine', prefix: 'lucide', suffix: '', dir: 'engine/js', out: 'engine/js/icons.js', extra: CHAPTER_ICONS, stripWrapper: true, fallback: 'circle-help' },
  { name: 'dashboard', prefix: 'solar', suffix: '-linear', dir: 'public/js', out: 'public/js/icons.js', extra: [], ignore: ['book-open'], stripWrapper: false, fallback: 'question-circle' },
];

function walk(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) return walk(p);
    return p.endsWith('.js') && !p.endsWith('icons.js') ? [p] : [];
  });
}

function collect(target) {
  const required = new Set(target.extra);
  const guessed = new Set();
  // required: names passed straight to icon() or listed as ico:/iconName:/icon: in data tables
  const direct = [/\bicon\(\s*'([a-z0-9-]+)'/g, /\b(?:ico|iconName|icon)\s*:\s*'([a-z0-9-]+)'/g];
  for (const file of walk(path.join(ROOT, target.dir))) {
    const src = fs.readFileSync(file, 'utf8');
    for (const re of direct) for (const m of src.matchAll(re)) required.add(m[1]);
    // best effort: any other quoted word that happens to be an icon (covers names inside ternaries)
    for (const m of src.matchAll(/'([a-z][a-z0-9]*(?:-[a-z0-9]+)*)'/g)) if (m[1].length <= 30) guessed.add(m[1]);
  }
  for (const n of target.ignore || []) required.delete(n);
  required.add(target.fallback);
  return { required: [...required], guessed: [...guessed].filter((g) => !required.has(g)) };
}

async function fetchIcons(prefix, names) {
  const found = {};
  const missing = [];
  for (let i = 0; i < names.length; i += 60) {
    const batch = names.slice(i, i + 60);
    const res = await fetch(`https://api.iconify.design/${prefix}.json?icons=${batch.map(encodeURIComponent).join(',')}`);
    if (!res.ok) throw new Error(`Iconify answered ${res.status} for ${prefix}`);
    const data = await res.json();
    for (const [name, icon] of Object.entries(data.icons || {})) found[name] = icon.body;
    for (const [alias, def] of Object.entries(data.aliases || {})) if (data.icons?.[def.parent]) found[alias] = data.icons[def.parent].body;
    for (const n of data.not_found || []) missing.push(n);
  }
  return { found, missing };
}

let failed = false;
for (const target of TARGETS) {
  const { required, guessed } = collect(target);
  if (target.name === 'dashboard' && !required.length) continue;
  const want = [...required, ...guessed].map((n) => `${n}${target.suffix}`);
  const { found } = await fetchIcons(target.prefix, want);
  const lost = required.filter((n) => !found[`${n}${target.suffix}`]);
  if (lost.length) {
    failed = true;
    console.error(`[${target.name}] icons that do not exist in ${target.prefix}:`, lost.join(', '));
  }
  const icons = {};
  for (const n of [...required, ...guessed]) {
    let body = found[`${n}${target.suffix}`];
    if (!body) continue;
    if (target.stripWrapper) {
      const m = body.match(/^<g [^>]*>([\s\S]*)<\/g>$/);
      if (m) body = m[1];
    }
    icons[n] = body;
  }
  const keys = Object.keys(icons).sort();
  const source = `// Generated by scripts/build-icons.mjs from Iconify (${target.prefix}). Do not edit by hand.\nexport const ICONS = {\n${keys.map((k) => `  ${JSON.stringify(k)}: ${JSON.stringify(icons[k])},`).join('\n')}\n};\n`;
  fs.writeFileSync(path.join(ROOT, target.out), source);
  console.log(`[${target.name}] ${keys.length} icons written to ${target.out} (${(source.length / 1024).toFixed(1)} KB)`);
}
if (failed) process.exit(1);
